window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ade8c63ad67cddc3"]={"versions": [{"id": "FIG-ade8c63ad67cddc3", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm im Interaktionsrahmen <code>sd Det_Initialization</code>. Dargestellt ist der synchrone Initialisierungs- und Startablauf des Development Error Tracers (DET) durch das ECU State Manager-Modul (EcuM) im Kontext der AUTOSAR-Basissoftware (BSW, System Services).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei BSW-Modulinstanzen (Stereotyp <code>«module»</code>) mit Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM::EcuM</code>: Ruft die Initialisierungsfunktionen auf.</li>\n<li><code>Det::Det</code>: Zielmodul für Initialisierung und Betriebsstart.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenaufrufe (C-APIs):</p>\n<ul class=\"fig-list\">\n<li><code>Det_Init()</code></li>\n<li><code>Det_Start()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchrone Sequenzabfolge:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM::EcuM</code> sendet synchronen Aufruf <code>Det_Init()</code> an <code>Det::Det</code>. Ein Kommentar vermerkt: „Comment: Initialization of Development Error Tracer is performed synchronously“.</li>\n<li>Nach Abschluss der Initialisierung antwortet <code>Det::Det</code> mit dem Rücksprung <code>Det_Init()</code> an <code>EcuM::EcuM</code>.</li>\n<li>Anschließend sendet <code>EcuM::EcuM</code> den synchronen Aufruf <code>Det_Start()</code> an <code>Det::Det</code>.</li>\n<li><code>Det::Det</code> beendet die Startroutine und kehrt mit <code>Det_Start()</code> zu <code>EcuM::EcuM</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Ablauf definiert die standardisierte Hochlaufsequenz des DET während der BSW-Initialisierungsphase. Beide Aufrufe sind als synchrone Funktionsaufrufe mit Blockierung bis zur Rückkehr modelliert. Ein Notizfeld unten weist Metadaten aus („Status: Proposed by TO as per SWS Det 1.5“, „Description:“, „Comment:“).</p>"}, {"id": "FIG-9127a6b1302fff05", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm ohne äußeren Rahmen. Dargestellt ist der synchrone Initialisierungs- und Startablauf des Development Error Tracers (Det) durch das ECU State Manager-Modul (EcuM) im Kontext der AUTOSAR-Basissoftware (BSW, System Services).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei BSW-Modulinstanzen (Stereotyp <code>«module»</code>) mit Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM</code>: Ruft die Initialisierungsfunktionen auf.</li>\n<li><code>Det</code>: Zielmodul für Initialisierung und Betriebsstart.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenaufrufe (C-APIs):</p>\n<ul class=\"fig-list\">\n<li><code>Det_Init()</code></li>\n<li><code>Det_Start()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchrone Sequenzabfolge:</p>\n<ol class=\"fig-list\">\n<li><code>EcuM::EcuM</code> sendet synchronen Aufruf <code>Det_Init()</code> an <code>Det::Det</code>. Ein Kommentar vermerkt: „Comment: Initialization of Development Error Tracer is performed synchronously“.</li>\n<li>Nach Abschluss der Initialisierung antwortet <code>Det::Det</code> mit dem Rücksprung <code>Det_Init()</code> an <code>EcuM::EcuM</code>.</li>\n<li>Anschließend sendet <code>EcuM::EcuM</code> den synchronen Aufruf <code>Det_Start()</code> an <code>Det::Det</code>.</li>\n<li><code>Det::Det</code> beendet die Startroutine und kehrt mit <code>Det_Start()</code> zu <code>EcuM::EcuM</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Ablauf definiert die standardisierte Hochlaufsequenz des DET während der BSW-Initialisierungsphase. Beide Aufrufe sind als synchrone Funktionsaufrufe mit Blockierung bis zur Rückkehr modelliert.</p>"}], "trans": [{"from": "FIG-ade8c63ad67cddc3", "to": "FIG-9127a6b1302fff05", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>UML-Rahmen <code>sd Det_Initialization</code> entfernt.</li>\n<li>Komponentenbezeichner in den Modul-Köpfen von vollqualifizierten Namen (<code>EcuM::EcuM</code>, <code>Det::Det</code>) zu einfachen Namen (<code>EcuM</code>, <code>Det</code>) vereinfacht.</li>\n<li>Metadaten-Notizblock („Status: Proposed by TO as per SWS Det 1.5“, „Description:“, „Comment:“) unten links entfernt.</li>\n</ul>"}]};
